            int meshes=Resources.FindObjectsOfTypeAll<Mesh>().Length,materials=Resources.FindObjectsOfTypeAll<Material>().Length,cameras=Resources.FindObjectsOfTypeAll<Camera>().Length;var definition=ScriptableObject.CreateInstance<PlanetDefinition>();definition.radius=120000;definition.terrainHeight=0;definition.stampTerrain=false;definition.oceanHeight=-35;definition.gravitationalParameter=9.81*120000*120000;
