                check(camp.pads[0].pose.Distance(camp.pads[1].pose)>179,"Neutral camp pads have separate full-size ship footprints");var publicCamp=SurvivalCampPresentation.Public(camp);string json=JsonUtility.ToJson(publicCamp);check(!json.Contains("\"stock\"")&&!json.Contains("\"inventory\"")&&!json.Contains("\"capacity\""),"Camp presentation exposes priced availability without serializing shop inventories");
