                var carrier=new Double3(10000,0,0);var suit=default(Double3);var position=new Double3(0,150000,0);for(int i=0;i<300;i++)SurvivalEvaKinematics.Step(ref position,ref carrier,ref suit,Vector3.forward,Vector3.up,Vector3.zero,false,1f/30,0);check(Math.Abs(carrier.x-10000)<1e-8&&suit.Magnitude<1e-8,"Releasing suit controls retains inherited orbital velocity instead of applying walking brakes");
