                var previous=local;previous.z=-38.3;check(ExitingSpaceDoor(rotating,previous,local),"Crossing an open airborne rear hatch is a valid EVA exit");rotating.rearOpen=false;check(!ExitingSpaceDoor(rotating,previous,local),"A closed hatch cannot be used to exit into space");rotating.rearOpen=true;var wrong=local;wrong.x=8;check(!ExitingSpaceDoor(rotating,previous,wrong),"EVA exit is limited to the physical airlock aperture");
