                DiagnosticMultipleSessions=true;host=new GameObject("Camp and EVA authority fixture");var session=host.AddComponent<SurvivalNetworkSession>();session.Config=new SurvivalServerConfig();session.surfaces.Add(1,surface);var world=new IndustrialWorld{multiplayer=new SurvivalSessionState{worldId="camp-native",instanceId="native"}};var owner=world.Register(1,camp.pose);var guest=world.Register(2,camp.pose);store=new IndustrialAuthority(world);session.authority=store;store.InitializeSurvivalCamp(camp);
