                SurvivalShipState Ship(ShipAssembly assembly,float height){var point=padPoint+new Double3(up)*height;return new SurvivalShipState{entity=assembly.id,owner=assembly.owner,pilot=assembly.owner,landed=false,pose=new FramePose{body=1,x=point.x,y=point.y,z=point.z},rotationX=rotation.x,rotationY=rotation.y,rotationZ=rotation.z,rotationW=rotation.w,physics=JsonUtility.ToJson(new PlanetShipSimulationSnapshot{pose=new SpacePose{position=point,rotation=rotation},assist=true,gear=true,heldClearance=height+8})};}
