                var control=ShipModules.P(-6.55,-4.2,-37.85);owner.pose=SurvivalShipInteriorModel.World(ship,control);check(session.ToggleShipDoor(peer,ship.entity,0)==null&&ship.rearOpen,"Authoritative hatch controls can open the outer airlock in flight");ship.rearOpen=false;owner.pose=ship.pose;
