                check(session.LandAtCamp(peer,camp.id,0)==null,"A cleared pad can be reserved again");for(int i=0;i<500&&ship.autoFlight;i++)session.SimulateShip(ship,layout,definition,default,1f/30);check(ship.landed&&!ship.autoFlight&&ship.pose.Distance(pad)<.5,"Automatic pad landing finishes on its recorded terrain contact pose");
                check(session.CampFlightAction(peer,true)==null&&ship.autoFlight,"Pad launch begins an automatic departure");for(int i=0;i<200&&ship.autoFlight;i++)session.SimulateShip(ship,layout,definition,default,1f/30);session.UpdateCamps();check(!ship.landed&&!ship.autoFlight&&ship.pose.Distance(pad)>200&&ship.landingCamp==0,"Automatic launch rises and moves clear of the pad before releasing its reservation");
            }finally{if(host!=null){var session=host.GetComponent<SurvivalNetworkSession>();session.authority=null;session.DisposeShipSimulations();session.ClearEntityViews();UnityEngine.Object.DestroyImmediate(host);}store?.Dispose();DiagnosticMultipleSessions=multiple;UnityEngine.Object.DestroyImmediate(definition);}
            check(meshes==Resources.FindObjectsOfTypeAll<Mesh>().Length&&materials==Resources.FindObjectsOfTypeAll<Material>().Length&&cameras==Resources.FindObjectsOfTypeAll<Camera>().Length,"Camp generation, EVA and pad authority allocate no rendering resources on the headless runtime");
